<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';Auth::requirePermission('surveys','view');$pageTitle='مدیریت نظرسنجی‌ها';$edit=null;
if(isset($_GET['delete'])&&Auth::verifyCsrf($_GET['csrf_token']??'')&&Auth::can('surveys','delete')){Database::execute('DELETE FROM surveys WHERE id=?',[(int)$_GET['delete']]);flash('نظرسنجی حذف شد.');redirect('/admin/surveys.php');}
if(isset($_GET['edit']))$edit=Database::fetch('SELECT * FROM surveys WHERE id=?',[(int)$_GET['edit']]);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/surveys.php');}$pdo=Database::connection();$pdo->beginTransaction();try{$id=(int)($_POST['id']??0);if(!Auth::can('surveys',$id?'edit':'create')){throw new RuntimeException('forbidden');}if($id){Database::execute('UPDATE surveys SET title=?,description=?,status=?,updated_at=NOW() WHERE id=?',[$_POST['title'],$_POST['description'],$_POST['status'],$id]);}else{Database::execute('INSERT INTO surveys (title,description,status,created_by,created_at,updated_at) VALUES (?,?,?,?,NOW(),NOW())',[$_POST['title'],$_POST['description'],$_POST['status'],Auth::user()['id']]);$id=(int)Database::lastInsertId();}Database::execute('DELETE FROM survey_kpis WHERE survey_id=?',[$id]);foreach($_POST['kpis']??[] as $kpiId){$k=Database::fetch('SELECT weight FROM kpis WHERE id=?',[(int)$kpiId]);if($k)Database::execute('INSERT INTO survey_kpis (survey_id,kpi_id,weight,created_at) VALUES (?,?,?,NOW())',[$id,(int)$kpiId,$k['weight']]);}Database::execute('DELETE FROM survey_assignments WHERE survey_id=?',[$id]);foreach($_POST['users']??[] as $uid){Database::execute('INSERT INTO survey_assignments (survey_id,user_id,assigned_by,status,created_at) VALUES (?,?,?,"assigned",NOW())',[$id,(int)$uid,Auth::user()['id']]);}$pdo->commit();flash('نظرسنجی ذخیره شد.');}catch(Throwable $e){$pdo->rollBack();flash('خطا در ذخیره نظرسنجی.','danger');}redirect('/admin/surveys.php');}
$kpis=Database::fetchAll('SELECT * FROM kpis WHERE status="active" ORDER BY title');$users=Database::fetchAll('SELECT * FROM users WHERE status="active" ORDER BY name');$surveys=Database::fetchAll('SELECT s.*,COUNT(DISTINCT sk.id) kpi_count,COUNT(DISTINCT sa.id) user_count FROM surveys s LEFT JOIN survey_kpis sk ON sk.survey_id=s.id LEFT JOIN survey_assignments sa ON sa.survey_id=s.id GROUP BY s.id ORDER BY s.id DESC');$selectedKpis=$edit?array_column(Database::fetchAll('SELECT kpi_id FROM survey_kpis WHERE survey_id=?',[$edit['id']]),'kpi_id'):[];$selectedUsers=$edit?array_column(Database::fetchAll('SELECT user_id FROM survey_assignments WHERE survey_id=?',[$edit['id']]),'user_id'):[];require __DIR__.'/../views/partials/admin-header.php';?>
<form class="card admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><h3>۱. اطلاعات نظرسنجی</h3><div class="grid grid-2"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($edit['title']??'')?>" required></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="active" <?=($edit['status']??'')==='active'?'selected':''?>>active</option><option value="disabled" <?=($edit['status']??'')==='disabled'?'selected':''?>>disabled</option></select></label><label class="form-field"><span>توضیحات</span><textarea name="description"><?=e($edit['description']??'')?></textarea></label></div><h3>۲. انتخاب KPI</h3><div class="checkbox-grid"><?php foreach($kpis as $k):?><label class="checkbox-item"><input type="checkbox" name="kpis[]" value="<?=$k['id']?>" <?=in_array($k['id'],$selectedKpis)?'checked':''?>> <?=e($k['title'])?> (<?=e($k['weight'])?>)</label><?php endforeach;?></div><h3>۳. تخصیص به کاربران</h3><div class="checkbox-grid"><?php foreach($users as $u):?><label class="checkbox-item"><input type="checkbox" name="users[]" value="<?=$u['id']?>" <?=in_array($u['id'],$selectedUsers)?'checked':''?>> <?=e($u['name'])?> - <?=e($u['role'])?></label><?php endforeach;?></div><div class="form-actions"><button class="btn btn-primary">ذخیره</button><a class="btn" href="/admin/surveys.php">جدید</a></div></form>
<div class="table-wrap"><table><thead><tr><th>عنوان</th><th>KPI</th><th>کاربران</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($surveys as $s):?><tr><td><?=e($s['title'])?></td><td><?=e($s['kpi_count'])?></td><td><?=e($s['user_count'])?></td><td><?=e($s['status'])?></td><td class="actions"><a class="btn btn-small" href="?edit=<?=$s['id']?>">ویرایش</a><a class="btn btn-small btn-danger" onclick="return confirm('حذف شود؟')" href="?delete=<?=$s['id']?>&csrf_token=<?=e(Auth::csrfToken())?>">حذف</a></td></tr><?php endforeach;?></tbody></table></div></section></main></div><script src="/assets/js/app.js"></script></body></html>
